prompt --application/shared_components/user_interface/templates/region/side_rail
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(354297297633821531)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TSideRail #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <div class="amc-TSideRail-layout">',
'    <header class="amc-TSideRail-rail">',
'      <span class="amc-TSideRail-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TSideRail-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <div class="amc-TSideRail-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </header>',
'    <div class="amc-TSideRail-main">',
'      <div class="amc-TSideRail-body">#BODY##SUB_REGIONS#</div>',
'      <footer class="amc-TSideRail-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'    </div>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Side Rail'
,p_internal_name=>'AMC_TPL_SIDE_RAIL'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-side-rail.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template with an editorial side rail. When the region is at least about 34rem wide, the title is set vertically in a rail at the start edge, reading upward, with the region icon above it and the Help, Edit, Change, Copy, Delete and Create buttons stacked below it; the region content takes the remaining width. Narrower regions switch automatically, through a container query, to a normal horizontal header. The rail mirrors in right-to-left languages. Previous, Close and Next sit in a footer under the content. Template options: Filled rail paints the rail with the primary color, Read downward sets the title top to bottom, Late switch keeps the top header until about 52rem, and No body padding. There is no motion; in forced-colors mode the rules use system colors.'
);
end;
